/****** Object:  UserDefinedFunction [dbo].[fnGetMeetingCount]    Script Date: 2/24/2026 9:08:09 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

	CREATE FUNCTION [dbo].[fnGetMeetingCount](@noteType NVARCHAR(12), @timePeriod NVARCHAR(3))
RETURNS INT
AS
BEGIN
	

	DECLARE @recordCount INT = 0;
	
	-- Check if a table exists
	DECLARE @tableName NVARCHAR(50);

	IF (@noteType = N'SYS_MEETB')
	BEGIN
		SET @tableName = 'UDFSYS_MEETB0';
	END
	ELSE IF (@noteType = N'SYS_MEETC')
	BEGIN
		SET @tableName = 'UDFSYS_MEETC0';
	END
	ELSE IF (@noteType = N'SYS_MEETS')
	BEGIN
		SET @tableName = 'UDFSYS_MEETS0';
	END
	ELSE
	BEGIN
		return -1;

	END

	IF (NOT EXISTS (SELECT * 
                 FROM INFORMATION_SCHEMA.TABLES 
                 WHERE TABLE_NAME = @tableName))
	BEGIN
		return -1;
	END

	-- Execute the logic
	IF (@timePeriod = N'12M')
	BEGIN
		-- Get count of meetings created in the system in the last 12 months
		IF (@noteType = N'SYS_MEETB')
		BEGIN
			-- Get count of Board Meetings
			SELECT	@recordCount = COUNT(UDFSYS_MEETB0.NOTEID)
			FROM	UDFSYS_MEETB0 WITH (NOLOCK)
					INNER JOIN AUDITTRAIL WITH (NOLOCK) ON UDFSYS_MEETB0.NOTEID = AUDITTRAIL.LINKID
			WHERE	((AUDITTRAIL.EVENTTYPE = 'NEWNOTE') AND (AUDITTRAIL.LINKQR = @noteType))
					AND (AUDITTRAIL.AUDITDATE > DATEADD(YEAR, -1, GETDATE()));
		END
		ELSE
		IF (@noteType = N'SYS_MEETC')
		BEGIN
			-- Get count of Committee Meetings
			SELECT	@recordCount = COUNT(UDFSYS_MEETC0.NOTEID)
			FROM	UDFSYS_MEETC0 WITH (NOLOCK)
					INNER JOIN AUDITTRAIL WITH (NOLOCK) ON UDFSYS_MEETC0.NOTEID = AUDITTRAIL.LINKID
			WHERE	((AUDITTRAIL.EVENTTYPE = 'NEWNOTE') AND (AUDITTRAIL.LINKQR = @noteType))
					AND (AUDITTRAIL.AUDITDATE > DATEADD(YEAR, -1, GETDATE()));
		END
		ELSE
		IF (@noteType = N'SYS_MEETS')
		BEGIN
			-- Get count of Shareholder Meetings
			SELECT	@recordCount = COUNT(UDFSYS_MEETS0.NOTEID)
			FROM	UDFSYS_MEETS0 WITH (NOLOCK)
					INNER JOIN AUDITTRAIL WITH (NOLOCK) ON UDFSYS_MEETS0.NOTEID = AUDITTRAIL.LINKID
			WHERE	((AUDITTRAIL.EVENTTYPE = 'NEWNOTE') AND (AUDITTRAIL.LINKQR = @noteType))
					AND (AUDITTRAIL.AUDITDATE > DATEADD(YEAR, -1, GETDATE()));
		END
	END
	ELSE
	IF (@timePeriod = N'90D')
	BEGIN
		-- Get count of meetings created in the system in the last 90 days
		IF (@noteType = N'SYS_MEETB')
		BEGIN
			-- Get count of Board Meetings
			SELECT	@recordCount = COUNT(UDFSYS_MEETB0.NOTEID)
			FROM	UDFSYS_MEETB0 WITH (NOLOCK)
					INNER JOIN AUDITTRAIL WITH (NOLOCK) ON UDFSYS_MEETB0.NOTEID = AUDITTRAIL.LINKID
			WHERE	((AUDITTRAIL.EVENTTYPE = 'NEWNOTE') AND (AUDITTRAIL.LINKQR = @noteType))
					AND (AUDITTRAIL.AUDITDATE > DATEADD(DAY, -90, GETDATE()));
		END
		ELSE
		IF (@noteType = N'SYS_MEETC')
		BEGIN
			-- Get count of Committee Meetings
			SELECT	@recordCount = COUNT(UDFSYS_MEETC0.NOTEID)
			FROM	UDFSYS_MEETC0 WITH (NOLOCK)
					INNER JOIN AUDITTRAIL WITH (NOLOCK) ON UDFSYS_MEETC0.NOTEID = AUDITTRAIL.LINKID
			WHERE	((AUDITTRAIL.EVENTTYPE = 'NEWNOTE') AND (AUDITTRAIL.LINKQR = @noteType))
					AND (AUDITTRAIL.AUDITDATE > DATEADD(DAY, -90, GETDATE()));
		END
		ELSE
		IF (@noteType = N'SYS_MEETS')
		BEGIN
			-- Get count of Shareholder Meetings
			SELECT	@recordCount = COUNT(UDFSYS_MEETS0.NOTEID)
			FROM	UDFSYS_MEETS0 WITH (NOLOCK)
					INNER JOIN AUDITTRAIL WITH (NOLOCK) ON UDFSYS_MEETS0.NOTEID = AUDITTRAIL.LINKID
			WHERE	((AUDITTRAIL.EVENTTYPE = 'NEWNOTE') AND (AUDITTRAIL.LINKQR = @noteType))
					AND (AUDITTRAIL.AUDITDATE > DATEADD(DAY, -90, GETDATE()));
		END
	END

	RETURN @recordCount;
END;
GO
/****** Object:  UserDefinedFunction [dbo].[GetMeetingRiskStatus]    Script Date: 2/24/2026 9:08:09 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[GetMeetingRiskStatus] (
@meetingStage int,
@meetingDate datetime2 )
RETURNS int AS BEGIN
Declare @daysToMeeting int;
Set @daysToMeeting = datediff(day, getutcdate(), @meetingDate);
If @meetingStage = 5 or @meetingStage = 6 BEGIN Return 0; END
if @meetingStage = 1 BEGIN If @daysToMeeting < 35 Return 3; If @daysToMeeting < 42 Return 2; Return 1; END
if @meetingStage = 2 BEGIN If @daysToMeeting < 28 Return 3; If @daysToMeeting < 32 Return 2; Return 1; END
if @meetingStage = 3 BEGIN If @daysToMeeting < 14 Return 3; If @daysToMeeting < 21 Return 2; Return 1; END
if @meetingStage = 4 BEGIN If @daysToMeeting < 2 Return 3; If @daysToMeeting < 10 Return 2; Return 1; END
Return 0; END
GO
