/****** Object:  Trigger [dbo].[Trigger_MeetingDelete]    Script Date: 2/24/2026 9:08:11 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TRIGGER [dbo].[Trigger_MeetingDelete]
ON [dbo].[Meetings]
FOR DELETE
AS
BEGIN
SET NOCOUNT ON
DELETE Participants
FROM DELETED D
INNER JOIN Participants P ON P.MeetingId = D.Id
END
GO
ALTER TABLE [dbo].[Meetings] ENABLE TRIGGER [Trigger_MeetingDelete]
GO
/****** Object:  Trigger [dbo].[T_NGDASHBOARDS_insert]    Script Date: 2/24/2026 9:08:11 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


-- Ensures that CREATEDBY and LASTEDTITEDBY are valid for new NGDASHBOARD entries.
create trigger [dbo].[T_NGDASHBOARDS_insert] on [dbo].[NGDASHBOARDS] after insert not for replication as
begin
	print 'Running T_NGDASHBOARDS_insert';
	-- CREATEDBY must be null if ISSHARED = 1 (and vice versa).
	-- And if CREATEDBY is not null then it must match a non-null record in USERS.USERID.
	if exists (select 1 from inserted
		left join USERS on inserted.CREATEDBY = USERS.USERID 
		where ((inserted.ISSHARED = 0 and inserted.CREATEDBY is null) or (inserted.ISSHARED = 1 and inserted.CREATEDBY is not null))
		or (inserted.CREATEDBY is not null and USERS.USERID is null))
	begin 
		throw 50042, 'NGDASHBOARDS insert error. Invalid value for CREATEDBY', 0;
	end
	
	-- LASTEDITEDBY should always be a valid USERS.USERID.
	if exists(select 1 from inserted
		left join USERS on inserted.LASTEDITEDBY = USERS.USERID
		where USERS.USERID is null)
	begin
		throw 50042, 'NGDASHBOARDS insert error. Invalid value for LASTEDITEDBY', 0;
	end
	
	-- LASTEDITED should not be null.
end
GO
ALTER TABLE [dbo].[NGDASHBOARDS] ENABLE TRIGGER [T_NGDASHBOARDS_insert]
GO
/****** Object:  Trigger [dbo].[T_NGDASHBOARDS_update]    Script Date: 2/24/2026 9:08:11 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- Ensures no USERID can be changed to an invalid value.
create trigger [dbo].[T_NGDASHBOARDS_update] on [dbo].[NGDASHBOARDS] after update not for replication as 
begin
	-- Were any USERIDs updated.
	declare @updated table (USERID nvarchar(12));
	
	insert into @updated (USERID)
		select i.CREATEDBY from inserted i join deleted d on i.DASHBOARDID = d.DASHBOARDID where i.CREATEDBY <> d.CREATEDBY
		union
		select i.LASTEDITEDBY from inserted i join deleted d on i.DASHBOARDID = d.DASHBOARDID where i.LASTEDITEDBY <> d.LASTEDITEDBY;

	-- Are any USERIDs invalid.
	if exists(select 1 from @updated u left join USERS on u.USERID = USERS.USERID where USERS.USERID is null)
	begin 
		throw 50042, 'NGDASHBOARDS update error. Invalid USERID', 0;
	end	
end
GO
ALTER TABLE [dbo].[NGDASHBOARDS] ENABLE TRIGGER [T_NGDASHBOARDS_update]
GO
/****** Object:  Trigger [dbo].[T_NGSAVEDLINKS_insert]    Script Date: 2/24/2026 9:08:11 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- Ensures that USERID, CREATEDBY and LASTEDTITEDBY are correct for new NGSAVEDLINKS entries.
create trigger [dbo].[T_NGSAVEDLINKS_insert] on [dbo].[NGSAVEDLINKS] after insert not for replication as
begin
	-- USERID should be a valid USERS.USERID or null.
	if exists (select 1 from inserted
		left join USERS on inserted.USERID = USERS.USERID 
		where inserted.USERID is not null
		and USERS.USERID is null)
	begin 
		throw 50042, 'NGSAVEDLINKS insert error. Invalid value for USERID', 0;
	end
	
	-- CREATEDBY should be a valid USERS.USERID.
	if exists (select 1 from inserted
		left join USERS on inserted.CREATEDBY = USERS.USERID 
		where USERS.USERID is null)
	begin 
		throw 50042, 'NGSAVEDLINKS insert error. Invalid value for CREATEDBY', 0;
	end
	
	-- LASTEDITEDBY should be a valid USERS.USERID.
	if exists(select 1 from inserted
		left join USERS on inserted.LASTEDITEDBY = USERS.USERID
		where USERS.USERID is null)
	begin
		throw 50042, 'NGSAVEDLINKS insert error. Invalid value for LASTEDITEDBY', 0;
	end
end
GO
ALTER TABLE [dbo].[NGSAVEDLINKS] ENABLE TRIGGER [T_NGSAVEDLINKS_insert]
GO
