-- Ensures no USERID can be changed to an invalid value.
create trigger [dbo].[T_NGSAVEDLINKS_update] on [dbo].[NGSAVEDLINKS] after update not for replication as 
begin
	-- Were any USERIDs updated.
	declare @updated table (USERID nvarchar(12));
	
	insert into @updated (USERID)
		select i.USERID from inserted i join deleted d on i.SAVEDLINKID = d.SAVEDLINKID where i.USERID <> d.USERID
		union
		select i.CREATEDBY from inserted i join deleted d on i.SAVEDLINKID = d.SAVEDLINKID where i.CREATEDBY <> d.CREATEDBY
		union
		select i.LASTEDITEDBY from inserted i join deleted d on i.SAVEDLINKID = d.SAVEDLINKID where i.LASTEDITEDBY <> d.LASTEDITEDBY;

	-- Are any USERIDs invalid.
	if exists(select 1 from @updated u left join USERS on u.USERID = USERS.USERID where USERS.USERID is null)
	begin 
		throw 50042, 'NGSAVEDLINKS update error. Invalid USERID', 0;
	end	
end
GO
ALTER TABLE [dbo].[NGSAVEDLINKS] ENABLE TRIGGER [T_NGSAVEDLINKS_update]
