/****** Object:  Trigger [dbo].[Trigger_ParticipantDelete]    Script Date: 2/24/2026 9:08:11 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TRIGGER [dbo].[Trigger_ParticipantDelete]
ON [dbo].[Participants]
INSTEAD OF DELETE
AS
BEGIN
SET NOCOUNT ON
UPDATE A
SET A.PresenterEntityGuid = NULL
FROM DELETED D
INNER JOIN AgendaItems A ON D.EntityGuid = A.PresenterEntityGuid AND D.MeetingId = A.MeetingId
DELETE Participants
FROM DELETED D
INNER JOIN Participants P ON P.ENTITYGUID = D.ENTITYGUID AND P.MeetingId = D.MeetingId
END
GO
ALTER TABLE [dbo].[Participants] ENABLE TRIGGER [Trigger_ParticipantDelete]
GO
